SET "departmentCode" = mapping."targetDepartment",
    "updatedAt" = CURRENT_TIMESTAMP
FROM mapping
WHERE resident."residentNo" = mapping."residentNo"
  AND COALESCE(resident."departmentCode", '') IS DISTINCT FROM mapping."targetDepartment";

