UPDATE "HousingBooking" AS booking
SET "departmentCode" = mapping."targetDepartment",
    "updatedAt" = CURRENT_TIMESTAMP
FROM mapping
LEFT JOIN "HousingResident" AS resident ON resident."residentNo" = mapping."residentNo"
WHERE (booking."employeeId" = mapping."residentNo" OR booking."residentId" = resident."id")
  AND COALESCE(booking."departmentCode", '') IS DISTINCT FROM mapping."targetDepartment";
